1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Assigns the owner's {@code memberId}, the single unified identity formatted
12	 * {@code <REGION><FY><HASH8><CHK>} where REGION is the region code derived from the postcode,
13	 * FY is the two-digit fiscal year of the registration date, HASH8 is the first 8 upper-case
14	 * hex characters of SHA-256 over {@code normalizedTelephone + lastName}, and CHK is a single
15	 * Luhn check digit over the digits of {@code <REGION><FY><HASH8>} (e.g. {@code NSW261A2B3C4D7}).
16	 * There is no sequence number; see {@link OwnerMemberId} for the exact derivation.
17	 *
18	 * <p>De-duplication: when the computed id already belongs to another owner, {@code -<n>} is
19	 * appended with the smallest {@code n} of 2 or more that makes it unique (so a first
20	 * collision yields {@code <base>-2}, the next {@code <base>-3}, and so on). The owner ends up
21	 * with the de-duplicated {@code memberId}.
22	 *
23	 * <p>Runs after {@code BuildOwner} (so the owner exists, with its telephone already
24	 * normalized to E.164 and its registration date rolled to a business day) but before
25	 * {@code SaveOwner} (so the owner being created is not yet persisted and cannot collide with
26	 * itself), mutating the owner in place.
27	 */
28	public class AssignMemberId {
29	
30	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
31	        String base = OwnerMemberId.of(owner.getPostcode(), owner.getCity(), owner.getTelephone(),
32	                owner.getLastName(), owner.getRegistrationDate());
33	
34	        Set<String> existing = new HashSet<>();
35	        for (Owner other : ownerRepository.findAll()) {
36	            if (owner.getId() != null && owner.getId().equals(other.getId())) {
37	                continue; // never de-duplicate against the owner being created
38	            }
39	            if (other.isDeleted()) {
40	                continue; // a soft-deleted owner's member id is free to reuse
41	            }
42	            String id = other.getMemberId();
43	            if (id != null) {
44	                existing.add(id);
45	            }
46	        }
47	
48	        String id = base;
49	        for (int n = 2; existing.contains(id); n++) {
50	            id = base + "-" + n;
51	        }
52	        owner.setMemberId(id);
53	    }
